CREATE TABLE IF NOT EXISTS "cart_items" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "cart_id" integer NOT NULL, "product_id" integer NOT NULL, "quantity" integer, "size" varchar, "color" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL, "variant_id" integer /*application='BrandStore'*/, CONSTRAINT "fk_rails_6cdb1f0139"
FOREIGN KEY ("cart_id")
