CREATE TABLE IF NOT EXISTS "categories" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar, "description" text, "featured" boolean, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
