CREATE TABLE IF NOT EXISTS "automations" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar, "description" text, "trigger_type" varchar, "action_type" varchar, "active" boolean, "schedule" varchar, "created_at" datetime(6) NOT NULL, "updated_at" datetime(6) NOT NULL);
