INSERT INTO action_text_rich_texts VALUES(104,'description','<div><strong>Ellesse Kids'' Line T-Shirt -&nbsp; White<br></strong><br></div><div><strong>Description:</strong>The Ellesse Kids'' Line T-Shirt is a versatile and stylish piece perfect for young fashion enthusiasts. Available in classic black or white, this T-shirt combines comfort and iconic branding, making it suitable for everyday wear and various activities.<br><br></div><div><strong><br>Features:<br></strong><br></div><ul><li><strong>Color Options:</strong> White</li><li><strong>Material:</strong> Soft and breathable cotton fabric for maximum comfort</li><li><strong>Neckline:</strong> Classic crew neck design</li><li><strong>Sleeves:</strong> Short sleeves for a casual look</li><li><strong>Logo:</strong> Ellesse logo prominently displayed on the chest in a contrasting colour</li><li><strong>Fit:</strong> Regular fit, providing ease of movement</li></ul><div><strong><br>Details:<br></strong><br></div><ul><li><strong>Brand:</strong> Ellesse</li><li><strong>Product:</strong> Kids'' Line T-Shirt</li><li><strong>Colour Options:</strong> Black or White</li><li><strong>Sizes:</strong> Available in various sizes suitable for children</li><li><strong>Care Instructions:</strong> Machine wash. Please refer to the garment care label for detailed instructions.</li></ul><div><strong><br>Product Highlights:<br></strong><br></div><ul><li><strong>Versatile Design:</strong> Available in both black and white, allowing for easy pairing with different bottoms.</li><li><strong>Comfortable Fit:</strong> Made from high-quality cotton, ensuring comfort for all-day wear.</li><li><strong>Iconic Branding:</strong> Features the signature Ellesse logo, adding a touch of sporty style to any outfit.</li></ul>','Product',2036,'2025-12-15 19:28:15.345149','2025-12-15 19:28:15.345149');
INSERT INTO action_text_rich_texts VALUES(105,'description','','Product',2037,'2025-12-15 19:32:32.829929','2025-12-15 19:32:32.829929');
INSERT INTO action_text_rich_texts VALUES(106,'description','','Product',2038,'2025-12-15 19:34:34.184985','2025-12-15 19:34:34.184985');
INSERT INTO action_text_rich_texts VALUES(107,'description','<div>Our Butterfly Dress is more than just a beautiful outfit—it''s a heartwarming experience that brings parents and daughters closer. With its pleated neckline and unique back slit design, this dress features a convenient string tie or zipper at the back, making it easy for little ones to dress with a little help from mom or dad.</div>','Product',2039,'2025-12-15 19:36:59.409073','2025-12-15 19:36:59.409073');
INSERT INTO action_text_rich_texts VALUES(108,'description','','Product',2040,'2025-12-15 19:38:44.674522','2025-12-15 19:38:44.674522');
